import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.DzGOF12C.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"성리학 등장의 배경","slug":"성리학-등장의-배경","link":"#성리학-등장의-배경","children":[]},{"level":2,"title":"성리학의 수용 경로","slug":"성리학의-수용-경로","link":"#성리학의-수용-경로","children":[]},{"level":2,"title":"조선 사림의 등장","slug":"조선-사림의-등장","link":"#조선-사림의-등장","children":[]},{"level":2,"title":"세대별 조선 성리학자","slug":"세대별-조선-성리학자","link":"#세대별-조선-성리학자","children":[]},{"level":2,"title":"성리학의 중심 개념","slug":"성리학의-중심-개념","link":"#성리학의-중심-개념","children":[]}],"relativePath":"philosophy/Korean-Philosophy/06. 조선 성리학의 전개.md","filePath":"philosophy/Korean-Philosophy/06. 조선 성리학의 전개.md"}'),e={name:"philosophy/Korean-Philosophy/06. 조선 성리학의 전개.md"};function l(a,t,g,i,h,p){return r(),n("div",null,[...t[0]||(t[0]=[s('<h2 id="성리학-등장의-배경" tabindex="-1">성리학 등장의 배경 <a class="header-anchor" href="#성리학-등장의-배경" aria-label="Permalink to &quot;성리학 등장의 배경&quot;">​</a></h2><p>고려 말, 권문세족의 대토지 소유가 심화되며 땅을 잃은 농민이 늘고 자유인이 감소해 국력이 쇠퇴, 국정 개혁의 필요성이 대두됨. 여기에 불교의 폐단 — 개인의 해탈에 치중하는 특성상 불교 사원이 세금과 재산의 도피처로 비대화되고, 승려의 증가로 국역이 결손되는 문제 — 도 개혁 요구의 배경이 됨. 고려에서 승려는 국사·왕사로 예우받으며 막대한 토지·노비·물품 기증·영리사업·고리대업을 통해 세속적 권위와 경제력을 함께 쥐고 있었음(&quot;승려는 이미 출가하고 나면 마땅히 위로는 군왕에게 절을 하지 않고 아래로는 부모에게 절을 하지 않으니…&quot; — 『고려사』).</p><h2 id="성리학의-수용-경로" tabindex="-1">성리학의 수용 경로 <a class="header-anchor" href="#성리학의-수용-경로" aria-label="Permalink to &quot;성리학의 수용 경로&quot;">​</a></h2><p>원(元)이 주자학을 관학화하고 1313년 『사서오경』을 과거 과목으로 지정하자, 고려인들이 원의 과거에 응시하기 위해 『사서집주』를 익히면서 자연스럽게 주자학을 수용함. 만권당(충선왕이 연경에 세운 서당)에서 이제현 등이 원의 성리학자들과 교류하며 이해의 폭이 넓어졌고, 공민왕 16년(1367) 성균관에 오경사서재가 건립되며 성리학이 급속히 확산됨 — 이색을 성균관 대사성에 임명해 이숭인·정몽주·정도전 등과 함께 성균관을 정비함.</p><p><strong>의문점</strong>: 성리학의 학문적 체계는 남송(1127~1279) 주희(1130~1200)에 의해 이루어졌는데, 왜 선진 학문인 성리학이 남송대가 아니라 원나라 때(충렬왕 15년, 1289년)에야 고려에 수용되었을까? 금나라의 대두로 고려-송 양국의 외교(사행)가 단절되었기 때문으로 보인다는 것이 학계의 설명(김상기, 1959).</p><p><strong>고려 말 성리학자 계보</strong>: 안향(1243~1306, 원에서 공자·주자 그림과 책을 필사해 옴) → 백이정 → 권보(『사서집주』 간행 주도) → 이제현 → 이곡 → 이색. 다만 이 계보는 『동국문헌록』(고종 연간)에 투영된 조선 후기 사림의 인식이며, 우탁 역시 독자적으로 정주학을 전수한 인물로 확인됨. 이색 문하에서 정몽주·정도전·이숭인·길재·권근이 배출됨.</p><p><strong>성리학의 특징</strong>: 리(理)의 법칙성과 내재성을 통해 인간과 자연을 동일한 지평에서 설명 — 인간의 심성이 곧 천리이므로, 유학자들은 그 천리를 온전히 실현하는 존재인 <strong>성인</strong>이 되기를 희망함(성학론). 이는 군주성학론에서 시작해 사대부 전체의 수양론으로 확산되며, &quot;경세제민(經世濟民)&quot;을 목표로 경학을 익히고 덕행을 닦는 일(經明行修之事)을 강조함 — <strong>수기(修己)는 치인(治人)을 위한 것이고, 치인은 수기의 완성</strong>이라는 구도가 자리잡음.</p><h2 id="조선-사림의-등장" tabindex="-1">조선 사림의 등장 <a class="header-anchor" href="#조선-사림의-등장" aria-label="Permalink to &quot;조선 사림의 등장&quot;">​</a></h2><p>성종의 개혁정치기에 언론(삼사)을 활성화해 훈구세력을 견제하는 과정에서 김종직이 발탁되고, 길재의 학맥을 이은 이들이 관직에 진출하며 &#39;사림파&#39;라는 정치세력이 형성됨(김종직 → 김굉필·정여창·김일손). 중종반정 이후 조광조(김굉필의 제자)가 현량과를 설치해 신진 선비를 대거 등용하고 각종 폐단 개혁을 시도했으나, 훈구파의 강력한 저항으로 <strong>기묘사화</strong>가 일어나 조광조 등이 사사됨.</p><p>조광조는 『소학』의 실천을 유독 강조했다 — &quot;유교를 국시로 하는 나라에서 어찌하여 사화나 반정 같은 일이 계속 일어나는가? 임금도 신하도 옛 가르침대로 행하지 않기 때문이다.&quot; **『소학』**은 주희가 50대 후반(1187년)에 편찬한 저작으로, 예기의 「곡례」·「소의」·「내칙」 등을 근거로 삼음. 어린이 대상의 책으로 오해되기 쉬우나 조선에서는 사서에 버금가는 비중을 지닌 성인 학자의 필독서로 다루어졌으며, 내편(입교·명륜·경신·계고)과 외편(가언·선행)으로 구성됨.</p><h2 id="세대별-조선-성리학자" tabindex="-1">세대별 조선 성리학자 <a class="header-anchor" href="#세대별-조선-성리학자" aria-label="Permalink to &quot;세대별 조선 성리학자&quot;">​</a></h2><ul><li><strong>2세대(이론화)</strong>: 서경덕(1489~1546)은 <strong>기철학</strong>으로 우주 질서를 설명했고, 이언적(1491~1553)은 주자학의 정통적 리 중심 성리설을 바탕으로 구체적 일상에서 출발하는 수양론을 전개함. 이황(1501~1570)과 기대승(1527~1572)의 <strong>사단칠정논쟁</strong>, 이이(1536~1588)와 성혼(1535~1598)의 <strong>인심도심논쟁</strong>이 이 시기의 대표 논쟁.</li><li><strong>3세대(분화와 예학)</strong>: 1575년 이조전랑 직책 계승 문제로 <strong>동인</strong>(이황·조식·서경덕 문하)과 <strong>서인</strong>(이이·성혼·송익필 문하)으로 분화. 이후 남인/북인, 노론/소론 등으로 정치적 붕당이 계속 갈라지는 한편, 17세기에는 예학이 발달(정구·김장생·박세채)하고 예송논쟁이 벌어짐.</li><li><strong>4세대</strong>: 권상하·한원진·윤봉구(異論, 훗날 호론) vs 김창협·이재·이간(同論, 훗날 낙론)의 <strong>호락논쟁</strong>(인물성동이논쟁). 리의 주재성을 강조하는 主理 계열(이현일·이재·이상정·이진상)과 主氣 계열(임성주 등)의 분화도 이 시기.</li><li><strong>새로운 조류</strong>: 실학파(이익-권철신-정약용), 북학파(홍대용·박지원·박제가), 고증학(김정희), 기철학(최한기).</li><li><strong>5세대</strong>: 화서학파(이항로), 노사학파(기정진), 한주학파(이진상), 간재학파(전우) 등이 위정척사 운동과 결합됨. 이후 동학(최제우), 개화파(김옥균·박영효)로 사상적 지형이 근대로 이어짐.</li></ul><h2 id="성리학의-중심-개념" tabindex="-1">성리학의 중심 개념 <a class="header-anchor" href="#성리학의-중심-개념" aria-label="Permalink to &quot;성리학의 중심 개념&quot;">​</a></h2><p>성리학의 핵심 개념은 <strong>심(心)·성(性)·정(情)·리(理)·기(氣)</strong> 다섯으로 요약되며, 각각 심성론(심·성·정)과 우주론·발생론·생성론(리·기), 가치론·인성론의 층위에 걸쳐 있음.</p><p><strong>주돈이의 태극도설(우주론)</strong>: &quot;무극이면서 태극이다(無極而太極). 태극이 움직여 양을 낳고, 그 움직임이 극에 달하면 고요해진다. 고요해지면 음을 낳고, 그 고요함이 극에 달하면 다시 움직인다.&quot; 한 번 움직이고 한 번 고요해짐이 서로의 뿌리가 되어 음양으로 나뉘어 양의(兩儀)가 형성됨. 양이 변하고 음이 합하여 수·화·목·금·토 <strong>오행</strong>을 낳고, 오행의 순조로운 펼쳐짐이 사계절의 운행이 됨. 오행은 하나의 음양이며, 음양은 하나의 태극이며, 태극은 본래 무극이다. 오직 사람만이 음양오행 가운데 가장 빼어난 기운을 받아 영묘하며, 형체가 생겨나면 정신이 지각을 일으키고, 오성(인의예지신)이 외물에 감응하여 움직여 선악이 나뉘고 만사가 생겨남. 성인은 중정인의(中正仁義)로 마음을 안정시키고 고요함을 주로 하여 사람의 표준을 세움.</p><p><strong>리(理)</strong>: 태극·천·도·성과 같은 층위에서 이해되며 ①<strong>자기원인성</strong>(그 이전이나 너머의 어떤 존재도 필요 없음), ②<strong>초월성</strong>(현상계를 넘어섬), ③<strong>완전성</strong>(흠 없이 완전무결함), ④<strong>보편성</strong>(만물에 두루 영향을 끼침)을 특징으로 함. 다만 리는 의지·의도가 없고(無情意), 계획하지 않으며(無計度), 능동적으로 활동하지 않는다(無造作)는 점에서 기와 구별됨. 주자는 태극(리)과 동정(기)의 관계를 사람과 말에 비유함 — &quot;태극은 사람과 같고 동정은 말과 같다. 말은 사람을 싣고 사람은 말을 탄다. 말이 한 번 나가고 들어올 때마다 사람 역시 함께 나가고 들어온다&quot;(『주자어류』) — 리와 기는 항상 서로 의지하면서도 서로 떨어지지 않는다는 것.</p><p><strong>심·성·정의 관계</strong>: 정이천의 &quot;<strong>성즉리</strong>(性卽理)&quot;와 장횡거의 &quot;<strong>심통성정</strong>(心統性情, 마음은 성과 정을 아우른다)&quot;이라는 두 명제는 서로 반박되지 않는다는 것이 주자의 입장. 성은 정과 상대하여 말한 것이고, 심은 성·정과 상대하여 말한 것이다 — 도리에 부합하는 것이 <strong>성</strong>, 움직이는 것이 <strong>정</strong>, 그것을 주재하는 것이 <strong>심</strong>이다. 마음에는 체와 용이 있어 미발(未發) 상태는 마음의 체이고 이발(已發) 상태는 마음의 용인데, 성은 마음속에 자리한 이치이고 그것을 주재·운용하는 것이 마음이며, 정은 그 성이 기에 의해 외부로 발현된 결과다. 이를 도식화하면 <strong>심통성정</strong>(마음이 성·정을 포괄·주재함) → <strong>성즉리</strong>(성은 곧 리) → <strong>성발위정</strong>(성이 기에 의해 정으로 발현됨)이라는 삼단 구도로 정리되며, 이 틀이 이후 사단칠정논쟁·인심도심논쟁이 벌어지는 공통의 이론적 무대가 됨.</p>',17)])])}const d=o(e,[["render",l]]);export{_ as __pageData,d as default};
